  "explain": "📖 법령 근거:\n| 「화장품법」(법률) 🎯 기출 | 화장품의 제조·수입·판매 및 수출 등에 관한 사항을 규정함으로써 국민 보건 향상과 화장품 산업의 발전에 기여함을 목적으로 함 |\n해설: 「화장품법」은 화장품의 제조·수입·판매 및 수출 등에 관한 사항을 규정함으로써 ‘국민 보건 향상과 화장품 산업의 발전에 기여함’을 목적으로 명시하고 있으므로 ③이 정답입니다. 따라서 이와 다른 내용을 제시한 ①, ②, ④, ⑤는 법에 명시된 입법 목적에 해당하지 않습니다.",
