  "explain": "📖 교재 근거:\n| 「화장품법」·「보건범죄 단속에 관한 특별조치법」을 위반하여 금고 이상의 형을 선고받고 그 집행이 끝나거나(집행이 끝난 것으로 보는 경우를 포함) 집행이 면제되지 아니한 자, 또는 금고 이상의 형의 집행유예를 선고받고 그 유예기간 중에 있는 자 | O | O | O |\n해설: 화장품제조업의 등록 결격사유에는 정신질환자(전문의 인정 제외), 피성년후견인 또는 파산선고를 받고 복권되지 않은 자, 화장품법 등을 위반하여 금고 이상의 형을 선고받고 집행이 끝나지 않은 자, 등록 취소 후 1년이 지나지 않은 자 등이 해당하므로 ①, ②, ③, ⑤번은 모두 결격사유에 해당합니다. 반면 '식약처장의 사전 승인을 받지 아니한 자'는 결격사유 규정에 포함되어 있지 않으므로 정답은 ④번입니다.",
