  "explain": "📖 교재 근거:\n| 기능성화장품 | 총리령으로 정하는 11가지 효능·효과 --- 심사 또는 보고서 제출 필수 |\n※ ② \"여드름을 항생제로 치료하는 기능\"은 의약품 효능으로 화장품 범위에 명백히 부합하지 않음 |\n해설: 기능성화장품의 효능·효과에는 미백(①), 주름(③), 자외선(④), 탈모(⑤), 여드름 등이 포함되어 있으나, ‘여드름을 항생제로 치료하는 기능’은 기능성화장품의 범위에 해당하지 않으므로 ②번이 정답입니다.",
  "source": "화장품법의 이해 (140제)",
