  "explain": "📖 법령 근거 (L409):\n① 법 제4조의2제1항에 따른 영유아 또는 어린이의 연령 기준은 다음 각 호의\n해설: 화장품법 시행규칙 제10조의2 제1항에 따르면 영유아의 연령 기준은 ‘3세 이하’로 규정되어 있으므로 ⑤번이 정답입니다. 따라서 영유아의 기준을 1세 이하, 2세 이하, 7세 이하, 6세 이하로 제시한 ①, ②, ③, ④번 선지는 규정에 부합하지 않아 틀렸습니다.",
