  "derivedFrom": "subject1_q8",
  "explain": "📖 교재 근거:\n| 유기농화장품 🎯 기출 | 유기농 원료, 동식물, 미네랄, 미생물 및 그 유래 원료 등을 함유한 화장품으로, ISO 16128-1 가이드라인에 따라 정의된 천연(유래) 및 유기농(유래) 원료를 사용하고, ISO 16128-2 가이드라인에 따라 계산하였을 때 중량 기준으로 유기농(유래) 함량이 전체 제품에서 10% 이상이어야 하며, 유기농(유래) 함량을 포함한 천연(유래) 함량이 전체 제품에서 95% 이상으로 구성된 화장품 |\n해설: 유기농화장품은 관련 기준에 따라 계산하였을 때 중량 기준으로 유기농(유래) 함량이 전체 제품에서 10% 이상이어야 하므로 정답은 ⑤번입니다. 따라서 유기농 원료 함량 기준으로 5%, 95%, 20%, 50%를 제시한 ①, ②, ③, ④는 옳지 않습니다.",
