  "explain": "📖 교재 근거:\n| 「화장품법」·「보건범죄 단속에 관한 특별조치법」을 위반하여 금고 이상의 형을 선고받고 그 집행이 끝나거나(집행이 끝난 것으로 보는 경우를 포함) 집행이 면제되지 아니한 자, 또는 금고 이상의 형의 집행유예를 선고받고 그 유예기간 중에 있는 자 | O | O | O |\n해설: 근거에 따르면 금고 이상의 형의 집행유예를 선고받고 그 유예기간 중에 있는 자는 결격 사유에 해당하므로 ③번이 정답입니다. 반면 고등학교 졸업 학력, 책임판매업 폐업 이력, 부정행위 적발 후 경과 기간, 인문계 졸업 등은 규정된 결격 사유에 해당하지 않습니다.",
