  "derivedFrom": "subject1_q15",
  "explain": "📖 교재 근거:\n| 1년 이하 징역 또는 1천만 원 이하 벌금 (징역형과 벌금형 함께 부과 가능) | • 영유아 또는 어린이 사용 화장품임을 표시·광고하기 위한 안전과 품질 입증 자료 작성·보관을 위반한 자<br>• 안전용기·포장의 기준을 위반한 자<br>• 의약품으로 잘못 인식할 수 있게 표시 또는 광고를 한 자<br>• 기능성화장품으로 잘못 인식할 수 있거나 안전성·유효성 심사 결과와 다른 내용의 표시·광고를 한 자<br>• 소비자를 속이거나 소비자가 잘못 인식하도록 할 우려가 있는 표시·광고를 하거나 판매한 자<br>• 화장품의 기재사항, 가격표시, 기재·표시상의 주의를 위반한 화장품 또는 의약품으로 잘못 인식할 수 있게 기재·표시된 화장품을 판매한 자<br>• 판매 목적이 아닌 제품의 홍보·판매 촉진 등을 위해 미리...\n해설: 식약처장이 고시한 기능성 유효성분의 함량을 사실 그대로 광고하는 행위는 소비자를 속이거나 잘못 인식하도록 할 우려가 있는 부당한 광고에 해당하지 않습니다. 반면 의약품이나 기능성화장품으로 잘못 인식하게 하는 등 소비자를 속이거나 잘못 인식하도록 할 우려가 있는 표시·광고 행위(②, ③, ④, ⑤)는 처벌 대상이 되는 위반행위에 해당합니다.",
