  "stem": "화장품 표시·광고 내용 중 실증(Proof)이 필요한 항목에 대해 식약처장으로부터 실증자료 제출을 요구받은 경우, 영업자는 요구받은 날부터 며칠 이내에 해당 자료를 제출해야 하는가? — 해당하는 것을 모두 고르시오.",
