  "explain": "📖 교재 근거:\n• 화장품책임판매업자가 중요한 유해사례를 알았거나 판매중지나 회수에 준하는 외국정부의 조치 등을 알았을 때에는 15일 이내에 신속보고 해야 하며, 정기보고는 매 반기 종료 후 1개월 이내에 식품의약품안전처장에게 보고 (단, 상시근로자 수가 2인 이하로서 직접 제조한 화장비누만을 판매하는 화장품책임판매업자는 해당 안전성 정보를 보고하지 아니할 수 있음)\n해설: 화장품책임판매업자가 중요한 유해사례 등 안전성 정보를 알았을 때에는 15일 이내에 신속보고를 해야 하므로 정답은 ①입니다. 따라서 3일, 7일, 24시간, 30일 이내로 제시된 나머지 선지(②, ③, ④, ⑤)는 규정된 보고 기한과 일치하지 않아 틀렸습니다.",
  "source": "화장품법의 이해 (140제)",
