  "explain": "📖 교재 근거:\n| 「화장품법」(법률) 🎯 기출 | 화장품의 제조·수입·판매 및 수출 등에 관한 사항을 규정함으로써 국민 보건 향상과 화장품 산업의 발전에 기여함을 목적으로 함 |\n해설: 「화장품법」(법률)은 화장품의 제조·수입·판매 및 수출 등에 관한 사항을 규정함으로써 국민 보건 향상과 화장품 산업의 발전에 기여함을 목적으로 규정하고 있으므로 ①이 옳습니다. 나머지 선지(②, ③, ④, ⑤)는 법률에 명시된 화장품법의 입법 목적에 해당하지 않습니다.",
  "source": "화장품법의 이해 (140제)",
