  "derivedFrom": "subject1_q25",
  "explain": "📖 교재 근거:\n| 맞춤형화장품판매업 | 신고 | • 맞춤형화장품판매업자의 변경(법인은 대표자 변경)<br>• 맞춤형화장품판매업소의 상호 변경(법인은 법인 명칭 변경)<br>• 맞춤형화장품판매업소의 소재지 변경<br>• 맞춤형화장품조제관리사의 변경 |\n해설: 화장품법상 고형 비누 등 단순 세정용 제품류의 단순 소분은 맞춤형화장품 소분 대상에서 제외되므로 맞춤형화장품판매업소에서 소분하여 판매할 수 없어 ⑤번이 정답입니다. 반면 ①, ②, ③, ④번은 소분 판매가 제외되는 유형에 해당하지 않아 옳지 않습니다.",
  "source": "화장품법의 이해 (140제)",
