  "derivedFrom": "subject1_q26",
  "explain": "📖 법령 근거 (L782):\n② 법 제10조제1항제3호에 따라 기재ㆍ표시를 생략할 수 있는 성분이란 다음 각 호의 성분을 말한다. (내용량 10mL 초과 50mL 이하 또는 중량 10g 초과 50g 이하 화장품의 전성분 표시 생략 규정)\n해설: 화장품법 시행규칙에 따르면 표시·기재를 생략할 수 있는 화장품 포장의 기준은 내용량이 10밀리리터(mL) 이하 또는 10그램(g) 이하이므로 정답은 ①입니다. 따라서 15g(mL) 이하, 30g(mL) 이하 등을 제시한 ②, ③, ④, ⑤는 규정된 기준에 부합하지 않는 오답입니다.",
