  "derivedFrom": "subject1_q34",
  "explain": "📖 교재 근거:\n### (1) 기능성화장품의 심사를 위한 제출 서류\n해설: 기능성화장품 심사를 위한 제출 서류에는 안전성에 관한 자료 등이 포함되지만, ③ '제품의 제조 비용 및 원가 분석 자료'는 심사 제출 서류의 범위에 속하지 않으므로 정답입니다. 반면 ① 안전성에 관한 자료 등은 실제로 심사를 받기 위해 제출해야 하는 서류에 해당하므로 오답 선지입니다.",
