  "derivedFrom": "subject1_q35",
  "explain": "📖 법령 근거 (L881):\n제37조(벌칙) ① 제3조의6, 제4조의2제1항, 제9조, 제13조, 제16조제1항제2호ㆍ제3호, 같은 조 제2항 또는 제28조의4제3항을 위반하거나, 제14조제4항에 따른 중지명령에 따르지 아니한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. (제3조의6 = 자격증 대여 등의 금지)\n해설: 화장품법 제37조제1항에 따르면 해당 규정 위반 시 1년 이하의 징역 또는 1천만 원 이하의 벌금에 처하도록 명시되어 있으므로 정답은 ④입니다. 따라서 다른 형량이나 벌금액, 자격 정지 등을 제시한 ①, ②, ③, ⑤는 옳지 않습니다.",
