  "explain": "📖 교재 근거 (L5):\n화장품의유형과유형별·함유성분별사용할때의주의사항표시\n해설: 식약처장이 지정하여 고시하는 바코드 표시 의무 대상 화장품은 국내에서 유통되는 모든 화장품(다만, 수출용 화장품은 제외)이므로 정답은 ③입니다. 따라서 특정 제품류나 규격에 한정된다고 명시한 나머지 선지(①, ②, ④, ⑤)는 옳지 않습니다.",
