  "explain": "📖 교재 근거 (L481):\n| (3) 화장품제조업의 등록을 위한 시설 기준 등 🎯 기출 | 제조 작업을 하는 시설을 갖춘 작업소(쥐·해충 및 먼지 등을 막을 수 있는 시설, 작업대 등 제조에 필요한 시설 및 기구, 가루 제거 시설) + 원료·자재 및 제품을 보관하는 보관소 + 품질검사를 위해 필요한 시험실 + 품질검사에 필요한 시설 및 기구 |\n> 해설: 화장품제조업 시설 기준에는 작업소, 보관소, 시험실이 포함되며, 완제품 매장은 포함되지 않는다.",
