  "explain": "📖 교재 근거:\n다음에 해당하는 화장품을 판매(수입대행형 거래를 목적으로 하는 알선·수여를 포함)하거나 판매할 목적으로 제조·수입·보관 또는 진열을 금지한다.\n<!-- story:slot:s48 -->\n해설: 화장품법상 기능성화장품의 심사를 받아야 하는 품목에 해당하지 않는 것은 ③번 ‘색소 침착 완화 효과를 목적으로 하는 화장품’입니다. 반면 ① 미백, ② 주름개선, ④ 자외선 차단, ⑤ 염모 효과를 목적으로 하는 화장품은 기능성화장품 심사 대상에 해당하므로 오답입니다.",
