  "explain": "📖 교재 근거:\n| 50만 원 | • 화장품의 생산실적 또는 수입실적 또는 화장품 원료의 목록 등을 보고하지 않은 자<br>• 맞춤형화장품 원료의 목록을 보고하지 않은 자<br>• 책임판매관리자 및 맞춤형화장품조제관리사가 매년 화장품의 안전성 확보 및 품질관리에 관한 교육을 받지 않는 경우<br>• 식품의약품안전처장이 필요 시 영업자에게 화장품 관련 법령 및 제도에 관한 교육을 명할 시 그 명령을 위반한 자<br>• 폐업신고를 하지 않은 자<br>• 화장품의 판매가격을 표시하지 않은 자 |\n해설: 제시된 규정에 따르면 맞춤형화장품조제관리사는 화장품의 안전성 확보 및 품질관리와 관련된 직무를 수행하므로, 맞춤형화장품이 아닌 ③ ‘일반 화장품의 제조 관리 업무’는 조제관리사의 직무에 해당하지 않아 정답입니다. 반면 맞춤형화장품의 혼합·소분, 품질·위생관리 및 안전성과 관련된 ①, ②, ④, ⑤는 조제관리사의 직무 영역에 해당하므로 옳지 않은 선지입니다.",
  "source": "화장품법의 이해 (140제)",
