  "explain": "📖 교재 근거:\n참고 --- 「화장품법」 제13조(부당한 표시·광고 행위 등의 금지) 1)\n해설: 화장품법 제13조에서는 의약품으로 잘못 인식할 우려가 있는 광고(④)나 사실과 다르게 소비자를 속이거나 잘못 인식하도록 할 우려가 있는 허위·과대·기만 광고(②, ③, ⑤)를 부당한 표시·광고 행위로 금지하고 있습니다. 따라서 법률 규정에서 직접적으로 금지 행위로 규정하고 있지 않은 ①번 '경쟁사 제품과의 비교 광고'는 금지되는 행위에 해당하지 않습니다.",
