  "explain": "📖 법령 근거 (L892):\n제36조(벌칙) ① 다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. (기능성화장품 심사를 받지 아니하고 제조·수입한 자 포함)\n해설: 화장품법상 기능성화장품 심사를 받지 않고 기능성화장품을 제조·수입한 자에 대한 벌칙은 3년 이하의 징역 또는 3천만 원 이하의 벌금에 해당하므로 정답은 ④번입니다. 따라서 다른 형벌 기준이나 과태료를 제시한 ①번, ②번, ③번, ⑤번은 오답입니다.",
