  "derivedFrom": "subject1_q55",
  "explain": "📖 교재 근거 (1.cosmetic-law):\n| 행정처분 감경 | 2분의 1까지 감경 또는 면제 (공익·기소유예·무단광고 등) |\n해설: 행정처분은 위반 횟수(최근 1년간 같은 위반행위 기준 등)와 위반 행위의 경중을 고려하여 감경 또는 가중 처분할 수 있으므로 ⑤번이 정답입니다. 따라서 처분 기준의 변경이 불가능하거나 가중·경감 중 어느 하나만 가능하다는 등의 선지(①, ②, ③, ④)는 옳지 않습니다.",
