  "derivedFrom": "subject1_q56",
  "explain": "📖 교재 근거:\n| 벌칙(화장품법) | 상위: 3년/3천만 원 (사위·허위 기재). 중위: 1년/1천만 원 (미등록 영업). 하위: 200만 원 이하 (과태료성). |\n해설: 화장품법상 해당 위반 행위에는 3년 이하의 징역 또는 3천만 원 이하의 벌금에 처하는 상위 벌칙이 적용되므로 정답은 ①입니다. 따라서 1년 이하의 징역 또는 1천만 원 이하의 벌금(②)이나 5년 이하의 징역 또는 5천만 원 이하의 벌금(③) 등을 제시한 나머지 선지는 옳지 않습니다.",
