  "explain": "📖 교재 근거:\n⑦ 개인정보 수집 목적을 달성할 수 있다면 익명 처리하고, 익명 처리로 목적 달성이 불가능할 때는 가명 처리 해야 한다.\n해설: 개인정보 수집 목적을 달성할 수 있다면 익명 처리를 우선해야 하며, 익명 처리로 목적 달성이 불가능할 때 가명 처리해야 한다.",
