  "explain": "📖 교재 근거:\n| 1천 명 이상의 정보 유출 시 | • 정보주체에게 유출 내용을 지체 없이 통지<br>• 인터넷 홈페이지에 7일 이상 게재 (홈페이지가 없을 경우 사업장 등의 보기 쉬운 장소에 7일 이상 게시)<br>• 유출 내용에 따른 통지 및 조치 결과를 지체없이 보호위원회 또는 대통령령으로 정하는 전문기관에 신고<br>• 개인정보처리자는 '72시간' 이내에 서면 동의 등의 방법으로 전문기관에 신고하여야 함 |\n해설: 1천 명 이상의 개인정보가 유출되었을 경우 인터넷 홈페이지에 7일 이상 게재하여야 하며, 홈페이지가 없을 때는 사업장 등의 보기 쉬운 장소에 7일 이상 게시해야 한다. 또한 개인정보처리자는 72시간 이내에 전문기관에 신고하여야 한다.",
