  "explain": "📖 교재 근거:\n#### 3.2 정보통신서비스 제공자는 정보통신서비스를 1년의 기간 동안 이용하지\n아니하는 이용자의 개인정보를 보호하기 위해 개인정보의 파기 등 필요한\n조치를 취한다. (다만, 그 기간에 대해 다른 법령 또는 이용자의 요청에\n해설: 정보통신서비스 제공자는 다른 법령 또는 이용자의 요청에 따라 달리 정한 경우가 아니라면, 정보통신서비스를 1년의 기간 동안 이용하지 아니하는 이용자의 개인정보를 보호하기 위해 개인정보의 파기 등 필요한 조치를 취해야 한다.",
